package net.officefloor.hq.app;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.asof.AsOfView;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.sheet.SheetArchive;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * A viewer sees every screen and changes nothing: every write to a sheet (POST or PUT) by a user the sheet makes
 * a viewer is refused with a 400 before any step runs, so nothing is written nor audited. The bulk actions are let
 * through: they refuse each selected item themselves (the claim status rules refuse a viewer), reporting 0 done.
 * An archived sheet refuses every write the same way, whoever makes it. So does a screen showing the sheet as of a
 * date (?asOf=), bulk actions included: nothing changes while the as-of date is set.
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class ViewerGuard extends OncePerRequestFilter {

    private static final Pattern SHEET_WRITE = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    /** The writes that report per-item counts, so a viewer's press goes through with every item refused. */
    private static final Set<String> BULK = Set.of("/claims/bulk-open", "/claims/bulk-settle");

    private final Roles roles;
    private final SheetArchive archive;

    public ViewerGuard(Roles roles, SheetArchive archive) {
        this.roles = roles;
        this.archive = archive;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String method = request.getMethod();
        String user = request.getParameter("user");
        if (("POST".equals(method) || "PUT".equals(method)) && request.getParameter(AsOfView.PARAM) != null
                && SHEET_WRITE.matcher(request.getRequestURI().substring(request.getContextPath().length())).matches()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Nothing changes while the sheet is shown as of a date");
            return;
        }
        if (("POST".equals(method) || "PUT".equals(method)) && user != null) {
            Matcher m = SHEET_WRITE.matcher(request.getRequestURI().substring(request.getContextPath().length()));
            if (m.matches() && !BULK.contains(m.group(2) == null ? "" : m.group(2))) {
                String sheet = URLDecoder.decode(m.group(1), StandardCharsets.UTF_8);
                if (Role.VIEWER.equals(roles.of(sheet, user))) {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST, "A viewer cannot change the sheet");
                    return;
                }
                if (archive.archived(sheet)) {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST, "An archived sheet cannot change");
                    return;
                }
            }
        }
        chain.doFilter(request, response);
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** One of a person's grades, in force from its from-date (yyyy-MM-dd; null when it applies from the beginning of time). */
export type GradeFrom = { grade: Grade; from: string | null };

// grade is the one in force on the sheet's today; grades are every one recorded, by from-date.
// retiredFrom is null unless the person is retired; once set, they count as retired whatever the date.
/** One of a person's holds: from its from-date to its to-date, both included (yyyy-MM-dd; to is null when it never ends). */
export type Hold = { from: string; to: string | null };

// holds are every one added, in that order; their OPEN claims dated within a hold count in no live total, unless
// bound by a statement; their other claims still do.
export type Person = {
  id: number;
  name: string;
  grade: Grade;
  version: number;
  retiredFrom: string | null;
  holds: Hold[];
  grades: GradeFrom[];
  /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
  terms: number | null;
  /** Whether the sheet's today is on or after retiredFrom: from then their OPEN and PENDING claims, unless bound by a
   *  statement, count in no live total. */
  retiredNow: boolean;
};

/** The person's grade in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it. */
export function gradeOn(person: Person, date: string): Grade | undefined {
  let found: GradeFrom | undefined;
  for (const g of person.grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** Whether the person has any hold. */
export const isHeld = (p: Person) => p.holds.length > 0;

/** Whether a date (yyyy-MM-dd) is within one of the person's holds. */
export const heldOn = (p: Person, date: string) =>
  p.holds.some((h) => date >= h.from && (h.to === null || date <= h.to));

export const isRetired = (p: Person) => p.retiredFrom !== null;

/** Whether a claim of the person's dated on the day (yyyy-MM-dd), open and not bound by a statement, is kept out of
 *  every live total: it is dated within one of their holds, or their retirement date is reached. */
export const setAsideOn = (p: Person, date: string) => p.retiredNow || heldOn(p, date);

export const peopleKey = (sheet: string) => ['people', sheet] as const;

/** The mutation key every action on a person's row shares, so the row shows only its latest action's refusal. */
export const personActionKey = (sheet: string, person: number) => ['person-action', sheet, person] as const;

export const peoplePath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;

/** Everyone on the sheet, in the order they were added. */
export function usePeople(sheet: string) {
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(peoplePath(sheet)),
  });
}

/** Whether retired people are listed: off until turned on, and kept in the URL so loading a sheet leaves it be. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useIsLatest } from '../../query/useIsLatest';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { isHeld, peopleKey, peoplePath, personActionKey } from './people';
import type { Person } from './people';

function HoldHeader() {
  return (
    <>
      <th>Hold</th>
      <th>Holds</th>
      <th />
    </>
  );
}

// Whether the person has any hold, each of their holds, and the dates and button that add one (a blank from-date
// is the sheet's today; a blank to-date never ends). Their OPEN claims dated within a hold count in no live total,
// unless bound by a statement; their other claims still do. A hold ends on its to-date.
function PersonHold({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const hold = useMutation({
    mutationKey: personActionKey(sheet, person.id),
    mutationFn: (dates: { from: string; to: string }) =>
      postJson<Person[]>(byUser(`${peoplePath(sheet)}/${person.id}/hold`, user), dates),
    onSuccess: (updated) => {
      queryClient.setQueryData(peopleKey(sheet), updated);
      setFrom('');
      setTo('');
    },
  });
  const act = useSubmitOnce(hold);
  const latest = useIsLatest(personActionKey(sheet, person.id), hold.submittedAt);

  return (
    <>
      <td data-testid="person-hold">{isHeld(person) ? 'yes' : 'no'}</td>
      <td>
        {person.holds.map((h, i) => (
          <div key={i} data-testid="person-hold-line">
            {h.from} – {h.to ?? ''}
          </div>
        ))}
      </td>
      <td>
        <input
          data-testid="person-hold-from"
          type="text"
          placeholder="from yyyy-mm-dd"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            hold.reset();
          }}
        />{' '}
        <input
          data-testid="person-hold-to"
          type="text"
          placeholder="to yyyy-mm-dd"
          value={to}
          onChange={(e) => {
            setTo(e.target.value);
            hold.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-hold-toggle"
          disabled={hold.isPending}
          onClick={() => act({ from: from.trim(), to: to.trim() })}
        >
          Hold
        </button>
        {hold.isError && latest && (
          <span data-testid="person-error" role="alert">
            {' '}That hold was refused.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 40, Component: HoldHeader }),
  PersonColumns.fill({ order: 40, Component: PersonHold }),
];
